do
    local mt = getrawmetatable(game);
    local oldnidx = mt.__newindex;
    setreadonly(mt, false);
    mt.__newindex = newcclosure(function(self, k, v)
        if (k == 'Text' and v == 'ABA GUI') then
            v = "Porn Hub"
        end;
        return oldnidx(self, k, v)
    end);
    setreadonly(mt, true)
end;

